 const report=async()=>{if(!selectedBooking)return;if(reportDetails.trim().length<10||reportDetails.trim().length>1000)return setMessage(t('invalidReportDetails'));setBusy(true);const fingerprint=JSON.stringify([selectedBooking.id,reportCategory,reportDetails.trim()]);try{if(!reportKeyRef.current||reportKeyRef.current.fingerprint!==fingerprint)reportKeyRef.current={fingerprint,key:await Crypto.randomUUID()};await act('report_safety',{booking_id:selectedBooking.id,category:reportCategory,details:reportDetails.trim(),idempotency_key:reportKeyRef.current.key},true);reportKeyRef.current=null;setReportDetails('');setMessage(t('reportSent'));}catch{}finally{setBusy(false);}};
